/* @autogenerated */
package net.civeira.phylax.feature.observe.access;

import java.util.Arrays;
import java.util.Collection;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import jakarta.enterprise.context.ApplicationScoped;
import net.civeira.phylax.common.exception.NotAllowedException;
import net.civeira.phylax.common.security.Actor;

/**
 * Access control of the viewer api, with the same security as the rest of the application: the
 * token is validated by the application (mp.jwt) and the actor of the request carries its roles;
 * here only the roles of each level are checked ({@code app.observe.access.roles.*}, any of them is
 * enough, case insensitive).
 *
 * <p>
 * The denials raise {@link NotAllowedException}, so the api answers as the rest of the application:
 * 401 to an anonymous request, 403 to an authenticated one without the roles.
 */
@ApplicationScoped
public class ObserveAccess {

  private final Map<ObserveLevel, Set<String>> roles = new EnumMap<>(ObserveLevel.class);
  private final String requiredScope;

  public ObserveAccess(
      final @ConfigProperty(name = "app.observe.access.roles.read",
          defaultValue = "OBSERVABILITY_READER") String read,
      final @ConfigProperty(name = "app.observe.access.roles.write",
          defaultValue = "OBSERVABILITY_ADMIN") String write,
      final @ConfigProperty(name = "app.observe.access.roles.admin",
          defaultValue = "OBSERVABILITY_ADMIN") String admin,
      final @ConfigProperty(
          name = "app.observe.access.required-scope") Optional<String> requiredScope) {
    roles.put(ObserveLevel.READ, names(read));
    roles.put(ObserveLevel.WRITE, names(write));
    roles.put(ObserveLevel.ADMIN, names(admin));
    this.requiredScope = requiredScope.orElse("").trim();
  }

  /**
   * @return the grant of the actor if it has {@code level}
   * @throws NotAllowedException if the actor is anonymous or has not the roles of the level
   */
  public ObserveGrant require(final Actor actor, final ObserveLevel level) {
    if (null == actor || !actor.isAuthenticated()) {
      throw new NotAllowedException("The observability viewer requires a signed user");
    }
    ObserveGrant grant = new ObserveGrant(actor.getName(), levels(actor));
    if (!grant.has(level)) {
      throw new NotAllowedException("The observability viewer requires one of the roles "
          + rolesFor(level) + (requiredScope.isEmpty() ? "" : " and the scope " + requiredScope));
    }
    return grant;
  }

  /** The levels of the actor from its roles (empty without the required scope). */
  public Set<ObserveLevel> levels(final Actor actor) {
    Set<ObserveLevel> result = EnumSet.noneOf(ObserveLevel.class);
    if (!requiredScope.isEmpty() && !actor.hasScope(requiredScope)) {
      return result;
    }
    Set<String> held = upper(actor.getRoles());
    roles.forEach((level, names) -> {
      if (held.stream().anyMatch(names::contains)) {
        result.add(level);
      }
    });
    return result;
  }

  /** The roles that grant {@code level}: its own and those of the levels that include it. */
  private Set<String> rolesFor(final ObserveLevel level) {
    return roles.entrySet().stream().filter(entry -> entry.getKey().includes(level))
        .flatMap(entry -> entry.getValue().stream())
        .collect(Collectors.toCollection(java.util.TreeSet::new));
  }

  private static Set<String> upper(final Collection<String> values) {
    return null == values ? Set.of()
        : values.stream().map(value -> value.toUpperCase(Locale.ROOT)).collect(Collectors.toSet());
  }

  private static Set<String> names(final String value) {
    return Arrays.stream(value.split(",")).map(String::trim).filter(name -> !name.isEmpty())
        .map(name -> name.toUpperCase(Locale.ROOT)).collect(Collectors.toUnmodifiableSet());
  }
}
